w=2400;h=1800
# We'll sample row 0 with many columns to see gradient/horizon etc.
cols=[0,50,100,150,200,250,300,400,500,600,700,800,900,1000,1100,1200,1300,1400,1500,1600,1700,1800,1900,2000,2100,2200,2300,2399]
rows=[0,300,600,800,850,900,950,1000,1100,1200,1300,1400,1500,1600,1700,1799]
# We'll read by streaming to capture these positions
sample_positions=set((r,c) for r in rows for c in cols)
values={}

with p.open('r') as f:
    f.readline(); f.readline(); f.readline()
    pix_index=0
    comp=0
    r=g=b=None
    for line in f:
        if not line.strip():
            continue
        for token in line.split():
            v=int(token)
            if comp==0:
                r=v; comp=1
            elif comp==1:
                g=v; comp=2
            else:
                b=v; comp=0
                row=pix_index//w
                col=pix_index%w
                if (row,col) in sample_positions:
                    values[(row,col)]=(r,g,b)
                    if len(values)==len(sample_positions):
                        break
                pix_index+=1
        if len(values)==len(sample_positions):
            break

# print grid
for r in rows:
    rowvals=[values[(r,c)] for c in cols]
    print(r, rowvals)
